module TopModule (
    input  logic clk,
    input  logic in,
    input  logic reset,
    output logic [7:0] out_byte,
    output logic done
);

    typedef enum logic [3:0] {
        IDLE  = 4'd0,
        DAT0  = 4'd1,
        DAT1  = 4'd2,
        DAT2  = 4'd3,
        DAT3  = 4'd4,
        DAT4  = 4'd5,
        DAT5  = 4'd6,
        DAT6  = 4'd7,
        DAT7  = 4'd8,
        STOP  = 4'd9,
        WAIT  = 4'd10
    } state_t;

    state_t state, next_state;
    logic [7:0] shift_reg;

    // State transition register
    always_ff @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        next_state = state;
        case (state)
            IDLE: begin
                if (in == 1'b0)
                    next_state = DAT0;
            end
            DAT0: next_state = DAT1;
            DAT1: next_state = DAT2;
            DAT2: next_state = DAT3;
            DAT3: next_state = DAT4;
            DAT4: next_state = DAT5;
            DAT5: next_state = DAT6;
            DAT6: next_state = DAT7;
            DAT7: next_state = STOP;
            STOP: begin
                if (in == 1'b1)
                    next_state = IDLE;
                else
                    next_state = WAIT;
            end
            WAIT: begin
                if (in == 1'b1)
                    next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Data shift register (LSB first)
    always_ff @(posedge clk) begin
        if (reset) begin
            shift_reg <= 8'b0;
        end else begin
            case (state)
                DAT0: shift_reg[0] <= in;
                DAT1: shift_reg[1] <= in;
                DAT2: shift_reg[2] <= in;
                DAT3: shift_reg[3] <= in;
                DAT4: shift_reg[4] <= in;
                DAT5: shift_reg[5] <= in;
                DAT6: shift_reg[6] <= in;
                DAT7: shift_reg[7] <= in;
                default: ;
            endcase
        end
    end

    assign out_byte = shift_reg;
    assign done = (state == STOP) && (in == 1'b1);

endmodule

